#!/usr/bin/env bash
set -euo pipefail

# Run from a Laravel 13 React playground checked out next to panels/support/forms/tables.
# Nothing generated by this script is committed; Composer installs a real module.
test -f artisan
test -f ../../panels/tests/integration/modular/InventoryServiceProvider.php

composer config repositories.lavertia-forms '{"type":"path","url":"../../forms","options":{"symlink":true,"versions":{"lavertia/forms":"0.2.0"}}}'
composer config repositories.lavertia-tables '{"type":"path","url":"../../tables","options":{"symlink":true,"versions":{"lavertia/tables":"0.2.0"}}}'

composer require internachi/modular --with-all-dependencies --no-scripts --no-interaction --prefer-dist --no-progress
php artisan package:discover --ansi
php artisan make:module inventory --accept-default-namespace

mkdir -p app-modules/inventory/src
cp -R ../../panels/tests/Fixtures/app-modules/inventory/src/Lavertia app-modules/inventory/src/
cp ../../panels/tests/integration/modular/InventoryServiceProvider.php \
    app-modules/inventory/src/Providers/InventoryServiceProvider.php

composer update modules/inventory --with-all-dependencies --no-scripts --no-interaction --prefer-dist --no-progress
php artisan package:discover --ansi

# The host keeps its existing Admin dashboard and enables an Inventory Panel.
# This temporary config is confined to the CI workspace.
cat > config/lavertia.php <<'PHP'
<?php

declare(strict_types=1);

return [
    'panels' => [
        'admin' => [
            'path' => 'admin',
            'middleware' => ['web', 'auth'],
            'pages' => [\App\Lavertia\Pages\DashboardPage::class],
        ],
        'inventory' => [
            'path' => 'inventory',
            'middleware' => ['web', 'auth'],
            'pages' => [\Lavertia\Panels\Pages\DashboardPage::class],
        ],
    ],
];
PHP

cp .env.example .env
php artisan key:generate --force
test -f database/database.sqlite || touch database/database.sqlite
php artisan migrate --force
mkdir -p storage/framework/views storage/framework/cache/data storage/framework/sessions
php artisan optimize:clear
php artisan modules:list

cp ../../panels/tests/integration/modular/LavertiaModularIntegrationPest.php \
    tests/Feature/LavertiaModularIntegrationTest.php

assert_module_routes() {
    php artisan route:list --path=admin --json > /tmp/lavertia-module-routes.json
    php -r '
        $routes = json_decode(file_get_contents("/tmp/lavertia-module-routes.json"), true, 512, JSON_THROW_ON_ERROR);
        $expected = [
            "lavertia.admin.inventory.overview" => "admin/inventory/overview",
            "lavertia.admin.inventory.reports.daily-stock" => "admin/inventory/reports/daily-stock",
        ];
        foreach ($expected as $name => $uri) {
            $matches = array_values(array_filter(
                $routes,
                static fn (array $route): bool =>
                    ($route["name"] ?? null) === $name &&
                    ($route["uri"] ?? null) === $uri
            ));
            if (count($matches) !== 1) {
                fwrite(STDERR, "Expected exactly one module route: {$name} ({$uri}), found ".count($matches)."\n");
                exit(1);
            }
        }
        echo "Module routes present exactly once.\n";
    '
}

echo "Checking uncached module discovery..."
assert_module_routes
php artisan test tests/Feature/LavertiaDashboardTest.php tests/Feature/LavertiaModularIntegrationTest.php --compact

echo "Checking Laravel config and route caching..."
php artisan config:cache
php artisan route:cache
assert_module_routes
php artisan test tests/Feature/LavertiaDashboardTest.php tests/Feature/LavertiaModularIntegrationTest.php --compact

echo "Checking route cache rebuild..."
php artisan route:clear
php artisan route:cache
assert_module_routes
echo "Real InterNACHI/modular integration passed."
